34	    '.dc-editable{cursor:text;outline:none;white-space:nowrap;border-radius:3px;padding:0 2px;margin:0 -2px}',
35	    '.dc-editable:focus{background:#fff;box-shadow:0 0 0 1.5px #c96442}',
