476	  const srcOrder = allIds.filter((k) => !hidden.includes(k));
477	
478	  const order = React.useMemo(() => {
479	    const kept = (sec.order || []).filter((k) => srcOrder.includes(k));
480	    return [...kept, ...srcOrder.filter((k) => !kept.includes(k))];
481	  }, [sec.order, srcOrder.join('|')]);
482	
483	  const byId = Object.fromEntries(artboards.map((a) => [a.props.id ?? a.props.label, a]));
484	
485	  // marginBottom counter-scales so the on-screen gap between sections stays
486	  // constant — otherwise at low zoom the (world-space) gap collapses while
487	  // the screen-constant sectionhead below it doesn't, and the title reads as
488	  // belonging to the section above. paddingBottom below is just enough for
489	  // the 24px artboard-header (abs-positioned above each card) plus ~8px, so
490	  // the title sits tight against its own row at every zoom.
491	  return (
492	    <div data-dc-section={sid}
493	      style={{ marginBottom: 'calc(80px * var(--dc-inv-zoom, 1))', position: 'relative' }}>
494	      <div style={{ padding: '0 60px' }}>
495	        <div className="dc-sectionhead" style={{ paddingBottom: 36 }}>
496	          <DCEditable tag="div" value={sec.title ?? title}
497	            onChange={(v) => ctx && sid && ctx.patchSection(sid, { title: v })}
498	            style={{ fontSize: 28, fontWeight: 600, color: DC.title, letterSpacing: -0.4, marginBottom: 6, display: 'inline-block' }} />
499	          {subtitle && <div style={{ fontSize: 16, color: DC.subtitle }}>{subtitle}</div>}
500	        </div>
501	      </div>
502	      <div style={{ display: 'flex', gap, padding: '0 60px', alignItems: 'flex-start', width: 'max-content' }}>
503	        {order.map((k) => (
504	          <DCArtboardFrame key={k} sectionId={sid} artboard={byId[k]} order={order}
505	            label={(sec.labels || {})[k] ?? byId[k].props.label}
506	            onRename={(v) => ctx && ctx.patchSection(sid, (x) => ({ labels: { ...x.labels, [k]: v } }))}
507	            onReorder={(next) => ctx && ctx.patchSection(sid, { order: next })}
508	            onDelete={() => ctx && ctx.patchSection(sid, (x) => ({
509	              hidden: [...(x.srcKey === srcKey ? (x.hidden || []) : []), k],
510	              srcKey,
511	            }))}
512	            onFocus={() => ctx && ctx.setFocus(`${sid}/${k}`)} />
513	        ))}
514	      </div>
515	      {rest}
516	    </div>
517	  );
518	}
