694	    const move = (ev) => {
695	      const dx = ev.clientX - startX;
696	      me.style.transform = `translateX(${dx / scale}px)`;
697	      const cur = homes[startIdx].x + dx;
698	      let nearest = 0, best = Infinity;
699	      for (let i = 0; i < slotXs.length; i++) {
700	        const d = Math.abs(slotXs[i] - cur);
701	        if (d < best) { best = d; nearest = i; }
702	      }
703	      if (liveOrder.indexOf(id) !== nearest) {
704	        liveOrder = order.filter((k) => k !== id);
705	        liveOrder.splice(nearest, 0, id);
706	        layout();
707	      }
708	    };
709	
710	    const up = () => {
711	      document.removeEventListener('pointermove', move);
712	      document.removeEventListener('pointerup', up);
713	      const finalSlot = liveOrder.indexOf(id);
714	      me.classList.remove('dc-dragging');
715	      me.style.transform = `translateX(${(slotXs[finalSlot] - homes[startIdx].x) / scale}px)`;
716	      // After the settle transition, kill transitions + clear transforms +
717	      // commit the reorder in the same frame so there's no visual snap-back.
718	      setTimeout(() => {
719	        for (const h of homes) { h.el.style.transition = 'none'; h.el.style.transform = ''; }
720	        if (liveOrder.join('|') !== order.join('|')) onReorder(liveOrder);
721	        requestAnimationFrame(() => requestAnimationFrame(() => {
722	          for (const h of homes) h.el.style.transition = '';
723	        }));
724	      }, 180);
725	    };
726	    document.addEventListener('pointermove', move);
727	    document.addEventListener('pointerup', up);
728	  };
729	
730	  return (
731	    <div ref={ref} data-dc-slot={id} style={{ position: 'relative', flexShrink: 0 }}>
732	      <div className="dc-header" style={{ color: DC.label }} onPointerDown={(e) => e.stopPropagation()}>
733	        <div className="dc-labelrow">
734	          <div className="dc-grip" onPointerDown={onGripDown} title="Drag to reorder">
735	            <svg width="9" height="13" viewBox="0 0 9 13" fill="currentColor"><circle cx="2" cy="2" r="1.1"/><circle cx="7" cy="2" r="1.1"/><circle cx="2" cy="6.5" r="1.1"/><circle cx="7" cy="6.5" r="1.1"/><circle cx="2" cy="11" r="1.1"/><circle cx="7" cy="11" r="1.1"/></svg>
736	          </div>
737	          <div className="dc-labeltext" onClick={onFocus} title="Click to focus">
738	            <DCEditable value={label} onChange={onRename} onClick={(e) => e.stopPropagation()}
739	              style={{ fontSize: 15, fontWeight: 500, color: DC.label, lineHeight: 1 }} />
740	          </div>
741	        </div>
742	        <div className="dc-btns">
743	          <div ref={menuRef} style={{ position: 'relative' }}>
744	            <button className="dc-kebab" title="More" onClick={() => setMenuOpen((o) => !o)}>
745	              <svg width="12" height="12" viewBox="0 0 12 12" fill="currentColor"><circle cx="2.5" cy="6" r="1.1"/><circle cx="6" cy="6" r="1.1"/><circle cx="9.5" cy="6" r="1.1"/></svg>
746	            </button>
747	            {menuOpen && (
748	              <div className="dc-menu" onPointerDown={(e) => e.stopPropagation()}>
749	                <button onClick={() => doExport('png')}>Download PNG</button>
750	                <button onClick={() => doExport('html')}>Download HTML</button>
751	                <hr />
752	                <button className="dc-danger"
753	                  onClick={() => { if (confirming) { setMenuOpen(false); onDelete(); } else setConfirming(true); }}>
754	                  {confirming ? 'Click again to delete' : 'Delete'}
755	                </button>
756	              </div>
757	            )}
758	          </div>
759	          <button className="dc-expand" onClick={onFocus} title="Focus">
760	            <svg width="12" height="12" viewBox="0 0 12 12" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round"><path d="M7 1h4v4M5 11H1V7M11 1L7.5 4.5M1 11l3.5-3.5"/></svg>
761	          </button>
762	        </div>
763	      </div>
764	      <div ref={cardRef} className="dc-card"
765	        style={{ borderRadius: 2, boxShadow: '0 1px 3px rgba(0,0,0,.08),0 4px 16px rgba(0,0,0,.06)', overflow: 'hidden', width, height, background: '#fff', ...style }}>
766	        {children || <div style={{ height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#bbb', fontSize: 13, fontFamily: DC.font }}>{id}</div>}
767	      </div>
768	    </div>
769	  );
770	}
771	
772	// Inline rename — commits on blur or Enter.
773	function DCEditable({ value, onChange, style, tag = 'span', onClick }) {
774	  const T = tag;
775	  return (
776	    <T className="dc-editable" contentEditable suppressContentEditableWarning
777	      onClick={onClick}
778	      onPointerDown={(e) => e.stopPropagation()}
779	      onBlur={(e) => onChange && onChange(e.currentTarget.textContent)}
780	      onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); e.currentTarget.blur(); } }}
781	      style={style}>{value}</T>
782	  );
783	}
784	
785	// ─────────────────────────────────────────────────────────────
786	// Focus mode — overlay one artboard; ←/→ within section, ↑/↓ across
787	// sections, Esc or backdrop click to exit.
788	// ─────────────────────────────────────────────────────────────
789	function DCFocusOverlay({ entry, sectionMeta, sectionOrder }) {
