820	  });
821	
822	  const { width = 260, height = 480, children } = artboard.props;
823	  const [vp, setVp] = React.useState({ w: window.innerWidth, h: window.innerHeight });
824	  React.useEffect(() => { const r = () => setVp({ w: window.innerWidth, h: window.innerHeight }); window.addEventListener('resize', r); return () => window.removeEventListener('resize', r); }, []);
825	  const scale = Math.max(0.1, Math.min((vp.w - 200) / width, (vp.h - 260) / height, 2));
826	
827	  const [ddOpen, setDd] = React.useState(false);
