829	    <button onClick={(e) => { e.stopPropagation(); onClick(); }}
830	      style={{ position: 'absolute', top: '50%', [dir]: 28, transform: 'translateY(-50%)',
831	        border: 'none', background: 'rgba(255,255,255,.08)', color: 'rgba(255,255,255,.9)',
832	        width: 44, height: 44, borderRadius: 22, fontSize: 18, cursor: 'pointer',
833	        display: 'flex', alignItems: 'center', justifyContent: 'center', transition: 'background .15s' }}
834	      onMouseEnter={(e) => (e.currentTarget.style.background = 'rgba(255,255,255,.18)')}
835	      onMouseLeave={(e) => (e.currentTarget.style.background = 'rgba(255,255,255,.08)')}>
836	      <svg width="18" height="18" viewBox="0 0 18 18" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
837	        <path d={dir === 'left' ? 'M11 3L5 9l6 6' : 'M7 3l6 6-6 6'} /></svg>
838	    </button>
