840	
841	  // Portal to body so position:fixed is the real viewport regardless of any
842	  // transform on DesignCanvas's ancestors (including the canvas zoom itself).
843	  return ReactDOM.createPortal(
844	    <div onClick={() => ctx.setFocus(null)}
845	      onWheel={(e) => e.preventDefault()}
846	      style={{ position: 'fixed', inset: 0, zIndex: 100, background: 'rgba(24,20,16,.6)', backdropFilter: 'blur(14px)',
847	        fontFamily: DC.font, color: '#fff' }}>
848	
849	      {/* top bar: section dropdown (left) · close (right) */}
850	      <div onClick={(e) => e.stopPropagation()}
851	        style={{ position: 'absolute', top: 0, left: 0, right: 0, height: 72, display: 'flex', alignItems: 'flex-start', padding: '16px 20px 0', gap: 16 }}>
852	        <div style={{ position: 'relative' }}>
853	          <button onClick={() => setDd((o) => !o)}
854	            style={{ border: 'none', background: 'transparent', color: '#fff', cursor: 'pointer', padding: '6px 8px',
855	              borderRadius: 6, textAlign: 'left', fontFamily: 'inherit' }}>
856	            <span style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
857	              <span style={{ fontSize: 18, fontWeight: 600, letterSpacing: -0.3 }}>{meta.title}</span>
858	              <svg width="11" height="11" viewBox="0 0 11 11" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" style={{ opacity: .7 }}><path d="M2 4l3.5 3.5L9 4"/></svg>
859	            </span>
860	            {meta.subtitle && <span style={{ display: 'block', fontSize: 13, opacity: .6, fontWeight: 400, marginTop: 2 }}>{meta.subtitle}</span>}
861	          </button>
862	          {ddOpen && (
863	            <div style={{ position: 'absolute', top: '100%', left: 0, marginTop: 4, background: '#2a251f', borderRadius: 8,
864	              boxShadow: '0 8px 32px rgba(0,0,0,.4)', padding: 4, minWidth: 200, zIndex: 10 }}>
865	              {sectionOrder.filter((sid) => sectionMeta[sid].slotIds.length).map((sid) => (
866	                <button key={sid} onClick={() => { setDd(false); const f = sectionMeta[sid].slotIds[0]; if (f) ctx.setFocus(`${sid}/${f}`); }}
867	                  style={{ display: 'block', width: '100%', textAlign: 'left', border: 'none', cursor: 'pointer',
868	                    background: sid === sectionId ? 'rgba(255,255,255,.1)' : 'transparent', color: '#fff',
869	                    padding: '8px 12px', borderRadius: 5, fontSize: 14, fontWeight: sid === sectionId ? 600 : 400, fontFamily: 'inherit' }}>
870	                  {sectionMeta[sid].title}
871	                </button>
872	              ))}
873	            </div>
874	          )}
875	        </div>
876	        <div style={{ flex: 1 }} />
877	        <button onClick={() => ctx.setFocus(null)}
878	          onMouseEnter={(e) => (e.currentTarget.style.background = 'rgba(255,255,255,.12)')}
879	          onMouseLeave={(e) => (e.currentTarget.style.background = 'transparent')}
880	          style={{ border: 'none', background: 'transparent', color: 'rgba(255,255,255,.7)', width: 32, height: 32,
881	            borderRadius: 16, fontSize: 20, cursor: 'pointer', lineHeight: 1, transition: 'background .12s' }}>×</button>
882	      </div>
883	
884	      {/* card centered, label + index below — only the card itself stops
885	          propagation so any backdrop click (including the margins around
886	          the card) exits focus */}
887	      <div
888	        style={{ position: 'absolute', top: 64, bottom: 56, left: 100, right: 100, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 16 }}>
889	        <div onClick={(e) => e.stopPropagation()} style={{ width: width * scale, height: height * scale, position: 'relative' }}>
890	          <div style={{ width, height, transform: `scale(${scale})`, transformOrigin: 'top left', background: '#fff', borderRadius: 2, overflow: 'hidden',
891	            boxShadow: '0 20px 80px rgba(0,0,0,.4)' }}>
892	            {children || <div style={{ height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#bbb' }}>{aid}</div>}
893	          </div>
894	        </div>
895	        <div onClick={(e) => e.stopPropagation()} style={{ fontSize: 14, fontWeight: 500, opacity: .85, textAlign: 'center' }}>
896	          {(sec.labels || {})[aid] ?? artboard.props.label}
897	          <span style={{ opacity: .5, marginLeft: 10, fontVariantNumeric: 'tabular-nums' }}>{idx + 1} / {peers.length}</span>
898	        </div>
899	      </div>
900	
901	      <Arrow dir="left" onClick={() => go(-1)} />
902	      <Arrow dir="right" onClick={() => go(1)} />
903	
904	      {/* dots */}
905	      <div onClick={(e) => e.stopPropagation()}
906	        style={{ position: 'absolute', bottom: 20, left: '50%', transform: 'translateX(-50%)', display: 'flex', gap: 8 }}>
