        <div style={{marginTop:18, borderTop:'1px solid '+COL.inkOnPaper, paddingTop:14, display:'flex', justifyContent:'space-between', alignItems:'flex-end'}}>
          <div style={{fontFamily:F.italic, fontStyle:'italic', fontSize:14, lineHeight:1.2}}>
