// Motion language — choreograph the analysis reveal

function Motion() {
  const [t, setT] = React.useState(0);
  const [playing, setPlaying] = React.useState(true);

  React.useEffect(() => {
    if (!playing) return;
    const start = performance.now() - t;
    let raf;
    const tick = () => {
      const elapsed = performance.now() - start;
      if (elapsed > 3200) { setT(0); }
      else { setT(elapsed); raf = requestAnimationFrame(tick); }
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [playing]);

  return (
    <div style={{
      width:'100%', height:'100%',
      background:'var(--ink)', color:'var(--text)',
      padding:'48px 64px',
      display:'grid', gridTemplateColumns:'380px 1fr', gap:48,
    }}>
      {/* Left — principles */}
      <div>
        <div style={{fontFamily:'var(--font-mono)', fontSize:11, letterSpacing:'0.2em', textTransform:'uppercase', color:'var(--signal)'}}>04 · Motion</div>
        <h2 style={{fontFamily:'var(--font-display)', fontWeight:500, fontSize:46, lineHeight:1, letterSpacing:'-0.02em', margin:'12px 0 24px'}}>
          Motion = <em style={{fontStyle:'italic'}}>diagnosis,</em> not delight.
        </h2>
        <p style={{fontFamily:'var(--font-sans)', fontSize:14, lineHeight:1.6, color:'var(--text-dim)'}}>
          Things move when something is <em>being measured</em> or <em>changing state.</em>
          Nothing animates for vibes. No bouncy springs, no parallax, no scroll-jacked reveals.
        </p>

        <div style={{borderTop:'1px solid var(--line)', marginTop:28, paddingTop:20, display:'flex', flexDirection:'column', gap:14}}>
          <Rule label="Easing" v="cubic-bezier(.2,.8,.2,1)" note="The 'iOS' ease — calm decel, never bouncy" />
          <Rule label="Duration" v="120 / 220 / 480ms" note="Hover · element · page" />
          <Rule label="Stagger" v="40ms" note="Between sibling reveals" />
          <Rule label="Score count-up" v="1400ms" note="ease-out cubic. The hero number." />
          <Rule label="Forbidden" v="bounce, spring overshoot, parallax, glow pulses" note="" forbidden />
        </div>
      </div>

      {/* Right — the 0→3000ms timeline */}
      <div style={{display:'flex', flexDirection:'column'}}>
        <div style={{display:'flex', justifyContent:'space-between', alignItems:'baseline', marginBottom:12}}>
          <div style={{fontFamily:'var(--font-mono)', fontSize:11, letterSpacing:'0.15em', color:'var(--text-mute)'}}>
            THE ANALYSIS REVEAL · 0ms → 3000ms
          </div>
          <button onClick={()=>{setT(0); setPlaying(true);}} style={{
            fontFamily:'var(--font-mono)', fontSize:11, color:'var(--signal)',
            background:'transparent', border:'1px solid var(--signal)', padding:'5px 12px',
            cursor:'pointer', letterSpacing:'0.1em',
          }}>↻ REPLAY</button>
        </div>

        {/* Live preview */}
        <MotionPreview t={t} />

        {/* Timeline */}
        <div style={{marginTop:18, position:'relative', height:240, borderTop:'1px solid var(--line)', borderBottom:'1px solid var(--line)', paddingTop:14}}>
          {/* playhead */}
          <div style={{
            position:'absolute', top:0, bottom:0, left: `${(t/3200)*100}%`,
            width:1, background:'var(--signal)', boxShadow:'0 0 0 1px rgba(198,255,61,0.2)',
          }} />
          {/* time markers */}
          <div style={{display:'flex', justifyContent:'space-between', fontFamily:'var(--font-mono)', fontSize:10, color:'var(--text-mute)', letterSpacing:'0.1em'}}>
            {[0,500,1000,1500,2000,2500,3000].map(ms=>(
              <span key={ms}>{ms}ms</span>
            ))}
          </div>
          {/* tracks */}
          <div style={{marginTop:14, display:'flex', flexDirection:'column', gap:8}}>
            <Track label="Score count-up" start={200} end={1600} t={t} color="var(--signal)" desc="0 → 87. Mono digits flicker; final number snaps and emits a 1-frame brighten." />
            <Track label="Hook bar (red)" start={900} end={1400} t={t} color="var(--hot)" desc="Red bar paints onto timeline 0:00–0:03. No fade — it draws left-to-right like a marker." />
            <Track label="Citation chips" start={1400} end={2400} t={t} color="var(--cool)" desc="4 chips stagger in (40ms apart), translateY(8px) → 0, opacity 0 → 1." />
            <Track label="Caption rewrites" start={2200} end={3000} t={t} color="var(--gold)" desc="Three cards fade up in parallel; numbers 'predicted lift' tick up like odometers." />
          </div>
        </div>

        <p style={{fontFamily:'var(--font-sans)', fontSize:13, lineHeight:1.55, color:'var(--text-dim)', marginTop:16, maxWidth:600}}>
          The whole reveal is <strong style={{color:'var(--text)'}}>3 seconds</strong>. Sections stream in like a real
          API response — not a JS-faked stagger. The score lands first because the score is the headline.
          Everything else is supporting evidence and arrives in narrative order: <em>what's the score → why it's that score → what to do.</em>
        </p>
      </div>
    </div>
  );
}

function Rule({label, v, note, forbidden}) {
  return (
    <div>
      <div style={{display:'flex', justifyContent:'space-between', alignItems:'baseline'}}>
        <span style={{fontFamily:'var(--font-mono)', fontSize:11, letterSpacing:'0.1em', color: forbidden ? 'var(--hot)' : 'var(--text-mute)'}}>{label}</span>
        <span style={{fontFamily:'var(--font-mono)', fontSize:12, color: forbidden ? 'var(--hot)' : 'var(--signal)'}}>{v}</span>
      </div>
      {note && <div style={{fontFamily:'var(--font-sans)', fontSize:12, color:'var(--text-mute)', marginTop:3}}>{note}</div>}
    </div>
  );
}

function Track({label, start, end, t, color, desc}) {
  const inRange = t >= start;
  const progress = Math.min(1, Math.max(0, (t - start) / (end - start)));
  return (
    <div>
      <div style={{display:'flex', alignItems:'center', gap:10, marginBottom:3}}>
        <div style={{fontFamily:'var(--font-mono)', fontSize:10, color:'var(--text-mute)', width:130, letterSpacing:'0.05em'}}>{label}</div>
        <div style={{flex:1, position:'relative', height:14, background:'rgba(255,255,255,0.04)'}}>
          <div style={{
            position:'absolute', top:0, bottom:0,
            left: `${(start/3000)*100}%`,
            width: `${((end-start)/3000)*100}%`,
            background: 'rgba(255,255,255,0.06)',
            border: `1px solid ${color}`,
          }} />
          <div style={{
            position:'absolute', top:0, bottom:0,
            left: `${(start/3000)*100}%`,
            width: `${((end-start)/3000)*100 * progress}%`,
            background: color,
            opacity: inRange ? 0.85 : 0,
          }} />
        </div>
      </div>
      <div style={{fontFamily:'var(--font-sans)', fontSize:11, lineHeight:1.45, color:'var(--text-mute)', paddingLeft:140}}>{desc}</div>
    </div>
  );
}

function MotionPreview({t}) {
  // score count-up 200-1600
  const scoreP = Math.max(0, Math.min(1, (t-200)/1400));
  const score = Math.round(scoreP * 87);
  // hook bar 900-1400
  const hookP = Math.max(0, Math.min(1, (t-900)/500));
  // chips 1400-2400 (4 chips, 40ms stagger, each 320ms)
  const chips = [0,1,2,3].map(i=>{
    const cs = 1400 + i*40;
    const cp = Math.max(0, Math.min(1, (t-cs)/320));
    return cp;
  });
  // caption cards 2200-3000
  const capP = Math.max(0, Math.min(1, (t-2200)/600));

  return (
    <div style={{
      background:'var(--ink-2)', border:'1px solid var(--line)',
      padding:'24px 28px', minHeight:200,
      display:'grid', gridTemplateColumns:'180px 1fr', gap:24, alignItems:'flex-start',
    }}>
      <div>
        <div style={{fontFamily:'var(--font-display)', fontSize:88, lineHeight:0.9, color:'var(--signal)'}}>{score}</div>
        <div style={{fontFamily:'var(--font-mono)', fontSize:10, color:'var(--text-mute)', letterSpacing:'0.15em', marginTop:4}}>VIRALITY / 100</div>
      </div>
      <div style={{display:'flex', flexDirection:'column', gap:12}}>
        {/* timeline w/ red hook bar */}
        <div style={{position:'relative', height:18, background:'rgba(255,255,255,0.05)'}}>
          <div style={{position:'absolute', left:0, top:0, bottom:0, width: `${hookP*15}%`, background:'var(--hot)'}} />
          <div style={{position:'absolute', left:'15%', top:0, bottom:0, width:1, background:'var(--text-mute)'}} />
          <div style={{position:'absolute', left:8, top:'50%', transform:'translateY(-50%)', fontFamily:'var(--font-mono)', fontSize:9, color: hookP > 0.3 ? 'white' : 'transparent', letterSpacing:'0.1em'}}>WEAK HOOK</div>
        </div>
        {/* chips */}
        <div style={{display:'flex', gap:6, flexWrap:'wrap'}}>
          {['0:01 hook','0:08 pacing','0:14 caption','0:22 CTA'].map((c,i)=>(
            <div key={i} style={{
              fontFamily:'var(--font-mono)', fontSize:10, padding:'4px 8px',
              border:'1px solid var(--cool)', color:'var(--cool)',
              opacity: chips[i],
              transform: `translateY(${(1-chips[i])*8}px)`,
            }}>{c}</div>
          ))}
        </div>
        {/* caption cards */}
        <div style={{display:'flex', gap:6, opacity: capP, transform:`translateY(${(1-capP)*8}px)`}}>
          {[12,28,41].map((lift,i)=>(
            <div key={i} style={{flex:1, border:'1px solid var(--line)', padding:'8px 10px', background:'rgba(255,255,255,0.02)'}}>
              <div style={{fontFamily:'var(--font-mono)', fontSize:9, color:'var(--gold)', letterSpacing:'0.1em'}}>+{Math.round(lift*capP)}% LIFT</div>
              <div style={{fontFamily:'var(--font-sans)', fontSize:11, color:'var(--text-dim)', marginTop:4, lineHeight:1.3}}>Caption variant {String.fromCharCode(65+i)}</div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

window.Motion = Motion;

