            <Alternative key={i} {...alt} />
          ))}
        </div>
      </motion.section>

      {/* PACING */}
      <motion.section {...fadeUp} className="pt-10">
        <Label>PACING</Label>
        <Heading>{analysis.pacing.note}</Heading>
        {analysis.pacing.cuts.map((c, i) => (
          <TimedItem key={i} time={`${c.at.toFixed(1)}s`} kind="cut">
            <strong style={{ color: "var(--color-text)" }}>{c.issue}</strong>{" "}
            <span style={{ color: "var(--color-text-dim)" }}>{c.fix}</span>
          </TimedItem>
        ))}
        {analysis.pacing.deadAir.map((d, i) => (
          <TimedItem
            key={i}
            time={`${d.start.toFixed(1)}–${d.end.toFixed(1)}s`}
            kind="deadair"
          >
            {d.why}
          </TimedItem>
        ))}
      </motion.section>

      {/* THUMBNAIL */}
      <motion.section {...fadeUp} className="pt-10">
        <Label>
          THUMBNAIL · BEST FRAME AT {analysis.thumbnail.bestFrameAt.toFixed(1)}s
        </Label>
        <Heading>{analysis.thumbnail.issue}</Heading>
        <FixLine>{analysis.thumbnail.fix}</FixLine>
      </motion.section>

      {/* CAPTION */}
      <motion.section {...fadeUp} className="pt-10">
        <Label>CAPTION</Label>
        <p
          className="mt-3 text-base"
          style={{ color: "var(--color-text-dim)" }}
        >
          <span
            style={{
              fontFamily: "var(--font-mono)",
              fontSize: 11,
              color: "var(--color-text-mute)",
              letterSpacing: "0.1em",
            }}
          >
            ORIGINAL ·{" "}
          </span>
          <span
            style={{
              fontFamily: "var(--font-mono)",
              color: "var(--color-text)",
            }}
          >
            {analysis.caption.original}
          </span>
        </p>
        {analysis.caption.deadWords.length > 0 && (
          <p
            className="mt-2 font-mono text-[11px]"
            style={{
              fontFamily: "var(--font-mono)",
              color: "var(--color-text-mute)",
              letterSpacing: "0.05em",
            }}
          >
            DEAD WORDS ·{" "}
            {analysis.caption.deadWords.map((w, i) => (
              <span key={i} style={{ color: "var(--color-hot)" }}>
                {w}
                {i < analysis.caption.deadWords.length - 1 ? ", " : ""}
              </span>
            ))}
          </p>
        )}
        <div className="mt-6 grid grid-cols-1 md:grid-cols-3 gap-4">
          {analysis.caption.rewrites.map((r, i) => (
            <Alternative key={i} {...r} />
          ))}
        </div>
      </motion.section>

      {/* TRENDING */}
      <motion.section {...fadeUp} className="pt-10">
        <Label>TRENDING RECOMMENDATIONS</Label>
        <p
          className="mt-2 font-mono text-[10px]"
          style={{
            fontFamily: "var(--font-mono)",
            color: "var(--color-text-mute)",
            letterSpacing: "0.1em",
          }}
        >
          NOTE · model-suggested, not a live trend feed (see README)
        </p>
        <div className="mt-4 grid grid-cols-1 md:grid-cols-2 gap-8">
          <div>
            <SubLabel>AUDIO</SubLabel>
            {analysis.trending.audio.map((a, i) => (
              <TimedItem key={i} time={a.name} kind="cool">
                {a.why}
              </TimedItem>
            ))}
          </div>
          <div>
            <SubLabel>HASHTAGS</SubLabel>
            {analysis.trending.hashtags.map((h, i) => (
              <TimedItem key={i} time={h.tag} kind="cool">
                {h.why}
              </TimedItem>
            ))}
          </div>
        </div>
      </motion.section>

      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: dur.element, ease, delay: 1.2 }}
        className="mt-16 pt-6 border-t font-mono text-[10px]"
        style={{
          borderColor: "var(--color-line)",
          fontFamily: "var(--font-mono)",
          color: "var(--color-text-mute)",
          letterSpacing: "0.15em",
        }}
      >
        Analysis complete · scored by gemini-flash-latest · Day 5 turns this
        into the streamed reveal
      </motion.div>
    </motion.div>
  )
}

/* ── Small atoms ──────────────────────────────────────────── */

function Label({ children }: { children: React.ReactNode }) {
  return (
    <div
      className="font-mono text-[11px]"
      style={{
        fontFamily: "var(--font-mono)",
        color: "var(--color-text-mute)",
        letterSpacing: "0.2em",
        textTransform: "uppercase",
      }}
    >
      {children}
    </div>
  )
}

function SubLabel({ children }: { children: React.ReactNode }) {
  return (
    <div
      className="font-mono text-[10px] mb-3"
      style={{
        fontFamily: "var(--font-mono)",
        color: "var(--color-text-mute)",
        letterSpacing: "0.15em",
      }}
    >
      {children}
    </div>
  )
}

function Heading({ children }: { children: React.ReactNode }) {
  return (
    <h2
      className="mt-3 max-w-[820px]"
      style={{
        fontFamily: "var(--font-display)",
        fontSize: "clamp(22px, 2.6vw, 32px)",
        lineHeight: 1.18,
        letterSpacing: "-0.015em",
        color: "var(--color-text)",
        fontWeight: 500,
      }}
    >
      {children}
    </h2>
  )
}

function FixLine({ children }: { children: React.ReactNode }) {
  return (
    <p
      className="mt-3 max-w-[820px] text-[15px] leading-relaxed"
      style={{ color: "var(--color-text-dim)" }}
    >
      <span
        style={{
          fontFamily: "var(--font-mono)",
          fontSize: 10,
          color: "var(--color-signal)",
          letterSpacing: "0.15em",
          marginRight: 8,
        }}
      >
        FIX
      </span>
      {children}
    </p>
  )
}

function Bar({ label, value }: { label: string; value: number }) {
  const color =
    value < 40
      ? "var(--color-hot)"
      : value < 60
        ? "var(--color-gold)"
        : "var(--color-signal)"
  return (
    <div>
      <div
        className="flex justify-between font-mono text-[10px] mb-2"
        style={{
          fontFamily: "var(--font-mono)",
          color: "var(--color-text-mute)",
          letterSpacing: "0.1em",
        }}
      >
        <span>{label}</span>
        <span style={{ color }}>{value}</span>
      </div>
      <div className="h-1 relative" style={{ background: "rgba(255,255,255,0.06)" }}>
        <div
          className="absolute left-0 top-0 bottom-0"
          style={{ width: `${value}%`, background: color }}
        />
      </div>
    </div>
  )
}

function Alternative({
  tone,
  text,
  predictedLift,
}: {
  tone: string
  text: string
  predictedLift: number
}) {
  const isHero = predictedLift >= 25
  return (
    <div
      className="border p-4 transition-[border-color,background] duration-[220ms]"
      style={{
        background: isHero ? "rgba(198,255,61,0.05)" : "transparent",
        borderColor: isHero
          ? "var(--color-signal)"
          : "var(--color-line)",
      }}
    >
      <div
        className="flex justify-between font-mono text-[10px]"
        style={{ fontFamily: "var(--font-mono)", letterSpacing: "0.1em" }}
      >
        <span
          style={{
            color: isHero ? "var(--color-signal)" : "var(--color-gold)",
          }}
        >
          +{predictedLift}% LIFT
        </span>
        <span style={{ color: "var(--color-text-mute)" }}>{tone}</span>
      </div>
      <p
        className="mt-3 text-[14px] leading-snug"
        style={{ color: "var(--color-text)" }}
      >
        {text}
      </p>
    </div>
  )
}

function TimedItem({
  time,
  kind,
  children,
}: {
  time: string
  kind: "cut" | "deadair" | "cool"
  children: React.ReactNode
}) {
  const color =
    kind === "cut"
      ? "var(--color-gold)"
      : kind === "deadair"
        ? "var(--color-hot)"
        : "var(--color-cool)"
  return (
    <div
      className="mt-4 pl-4 max-w-[820px]"
      style={{ borderLeft: `2px solid ${color}` }}
    >
      <div
        className="font-mono text-[10px] mb-1.5"
        style={{
          fontFamily: "var(--font-mono)",
          color,
          letterSpacing: "0.1em",
        }}
      >
        {time}
      </div>
      <div
        className="text-[14px] leading-relaxed"
        style={{ color: "var(--color-text-dim)" }}
      >
        {children}
      </div>
    </div>
  )
}

