    if (v.videoWidth) setAspectRatio(`${v.videoWidth} / ${v.videoHeight}`)
    setIsPlaying(!v.paused)
    setCurrentTime(v.currentTime)

    return () => {
      v.removeEventListener("loadedmetadata", onMeta)
      v.removeEventListener("timeupdate", onTime)
