// Final canvas — desktop + mobile side by side

const { DesignCanvas, DCSection, DCArtboard, ReportDesktop, ReportMobile } = window;

function App() {
  return (
    <DesignCanvas title="Report v2 · Final" subtitle="A's structure + C's watermarks + real video & content">
      <DCSection id="desktop" title="Desktop · 1440">
        <DCArtboard id="desktop" label="Full report — desktop" width={1440} height={3800}>
          <ReportDesktop/>
        </DCArtboard>
      </DCSection>

      <DCSection id="mobile" title="Mobile · 430">
        <DCArtboard id="mobile" label="Full report — mobile" width={430} height={3400}>
          <ReportMobile/>
        </DCArtboard>
      </DCSection>
    </DesignCanvas>
  );
}

ReactDOM.createRoot(document.getElementById('root')).render(<App/>);

// Mobile version — final report design
// 430 wide. Single column. Same content, condensed.

const { REPORT: M_REPORT, V2_C, V2_F, V2_Watermark, V2_MonoTag, V2_Pill, V2_btn } = window;

function ReportMobile() {
  return (
    <div style={{background:V2_C.ink, color:V2_C.text, minHeight:'100%', fontFamily:V2_F.sans, overflow:'hidden'}}>
      <MHeader/>
      <MHero/>
      <MVideo/>
      <MFixHook/>
      <MFixPacing/>
      <MFixThumbnail/>
      <MFixCaption/>
      <MApplyCTA/>
      <MTrending/>
      <MFooter/>
    </div>
  );
}

function MHeader() {
  return (
    <header style={{padding:'14px 22px', borderBottom:`1px solid ${V2_C.line}`, display:'flex', justifyContent:'space-between', alignItems:'center', background:V2_C.ink, position:'sticky', top:0, zIndex:5}}>
      <div style={{display:'flex', alignItems:'center', gap:8}}>
        <div style={{width:12, height:12, background:V2_C.signal}}/>
        <span style={{fontFamily:V2_F.mono, fontSize:12, fontWeight:600, letterSpacing:'0.04em'}}>METRIC.fyi</span>
      </div>
      <div style={{fontFamily:V2_F.mono, fontSize:9, color:V2_C.dim, letterSpacing:'0.12em', display:'flex', alignItems:'center', gap:6}}>
        <span style={{width:5, height:5, background:V2_C.signal, borderRadius:'50%'}}/>
        <span>READY · {M_REPORT.shortId.replace('/r/','')}</span>
      </div>
      <button style={{fontFamily:V2_F.mono, fontSize:11, color:V2_C.signal, background:'transparent', border:'none', cursor:'pointer', letterSpacing:'0.1em', padding:0}}>↗</button>
    </header>
  );
}

function MHero() {
  return (
    <section style={{padding:'32px 22px 28px', position:'relative', overflow:'hidden', borderBottom:`1px solid ${V2_C.line}`}}>
      <V2_Watermark size={300} opacity={0.06} right={-30} top={-20}>{M_REPORT.score}</V2_Watermark>

      <div style={{position:'relative'}}>
        <div style={{display:'flex', alignItems:'center', gap:8, marginBottom:14, flexWrap:'wrap'}}>
          <V2_MonoTag>VIRALITY · {M_REPORT.creator}</V2_MonoTag>
          <V2_Pill color={V2_C.dim}>{M_REPORT.category}</V2_Pill>
        </div>

        <div style={{display:'flex', alignItems:'flex-end', gap:12}}>
          <span style={{fontFamily:V2_F.display, fontWeight:600, fontSize:180, lineHeight:0.78, color:V2_C.signal, letterSpacing:'-0.05em'}}>
            {M_REPORT.score}
          </span>
          <div style={{paddingBottom:14, fontFamily:V2_F.mono, fontSize:10, color:V2_C.mute, letterSpacing:'0.18em'}}>
            / 100
          </div>
        </div>

        <div style={{fontFamily:V2_F.mono, fontSize:10, color:V2_C.dim, letterSpacing:'0.1em', marginTop:12, display:'grid', gridTemplateColumns:'auto auto auto', gap:16}}>
          <span>vs MEDIAN · <span style={{color:V2_C.hot}}>{M_REPORT.vsMedian}</span></span>
          <span>vs CAT · <span style={{color:V2_C.hot}}>{M_REPORT.vsCategory}</span></span>
          <span>CEIL · <span style={{color:V2_C.signal}}>{M_REPORT.ceiling}↑</span></span>
        </div>

        <div style={{fontFamily:V2_F.sans, fontStyle:'italic', fontSize:18, lineHeight:1.35, color:V2_C.text, marginTop:22, letterSpacing:'-0.005em'}}>
          "{M_REPORT.verdict}"
        </div>

        <div style={{marginTop:22, display:'grid', gridTemplateColumns:'1fr 1fr', gap:14}}>
          {M_REPORT.bars.map(b => (
            <div key={b.l}>
              <div style={{display:'flex', justifyContent:'space-between', alignItems:'baseline', marginBottom:6}}>
                <span style={{fontFamily:V2_F.mono, fontSize:10, color:V2_C.dim, letterSpacing:'0.15em'}}>{b.l}</span>
                <span style={{fontFamily:V2_F.display, fontWeight:600, fontSize:22, color:b.hot?V2_C.hot:V2_C.signal, letterSpacing:'-0.02em', lineHeight:0.9}}>{b.v}</span>
              </div>
              <div style={{height:3, background:'rgba(255,255,255,0.08)', position:'relative'}}>
                <div style={{position:'absolute', left:0, top:0, bottom:0, width:`${b.v}%`, background:b.hot?V2_C.hot:V2_C.signal}}/>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

function MVideo() {
  const [time, setTime] = React.useState(0);
  const [playing, setPlaying] = React.useState(false);
  const [duration, setDuration] = React.useState(M_REPORT.duration);
  const videoRef = React.useRef(null);

  const seek = (t) => {
    if (videoRef.current) { videoRef.current.currentTime = t; setTime(t); }
  };
  const togglePlay = () => {
    if (!videoRef.current) return;
    if (playing) videoRef.current.pause(); else videoRef.current.play();
    setPlaying(!playing);
  };

  return (
    <section style={{padding:'28px 22px 28px', borderBottom:`1px solid ${V2_C.line}`}}>
      <V2_MonoTag>THE VIDEO · {M_REPORT.duration}s</V2_MonoTag>
      <h2 style={{fontFamily:V2_F.display, fontWeight:600, fontSize:28, lineHeight:1.05, letterSpacing:'-0.02em', margin:'8px 0 16px'}}>
        5 moments. <em style={{fontStyle:'italic', color:V2_C.hot}}>Two cost retention.</em>
      </h2>

      <div style={{position:'relative', background:V2_C.ink2, border:`1px solid ${V2_C.line}`}}>
        <video
          ref={videoRef}
          src={M_REPORT.videoUrl}
          style={{width:'100%', display:'block', aspectRatio:'9/16', maxHeight:520, objectFit:'cover', background:'#000'}}
          muted playsInline
          onTimeUpdate={e => setTime(e.target.currentTime)}
          onLoadedMetadata={e => setDuration(e.target.duration || M_REPORT.duration)}
          onClick={togglePlay}
        />
        {!playing && (
          <button onClick={togglePlay} style={{
            position:'absolute', top:'50%', left:'50%', transform:'translate(-50%,-50%)',
            width:60, height:60, borderRadius:'50%',
            background:'rgba(198,255,61,0.95)', color:V2_C.ink,
            border:'none', cursor:'pointer', fontSize:22, fontWeight:700, paddingLeft:5,
          }}>▶</button>
        )}
        <div style={{padding:'10px 14px', display:'flex', alignItems:'center', gap:12, background:'rgba(0,0,0,0.4)', position:'absolute', bottom:0, left:0, right:0}}>
          <button onClick={togglePlay} style={{fontFamily:V2_F.mono, fontSize:13, color:'white', background:'transparent', border:'none', cursor:'pointer', width:24}}>{playing ? '❚❚' : '▶'}</button>
          <div style={{fontFamily:V2_F.mono, fontSize:11, color:'white', letterSpacing:'0.05em'}}>
            {fmtM(time)} / {fmtM(duration)}
          </div>
        </div>
      </div>

      {/* timeline strip */}
      <div style={{marginTop:12, position:'relative'}}>
        <div style={{height:30, position:'relative'}}>
          <div style={{position:'absolute', top:12, left:0, right:0, height:6, background:'rgba(255,255,255,0.06)'}}/>
          <div style={{position:'absolute', top:12, left:0, height:6, background:V2_C.signal, width:`${Math.min(100, (time/duration)*100)}%`}}/>
          {M_REPORT.markers.map((m,i)=>(
            <div key={i} onClick={()=>seek(m.t)} style={{
              position:'absolute', top:0, bottom:0,
              left:`${(m.t/duration)*100}%`,
              transform:'translateX(-50%)',
              cursor:'pointer', padding:'0 4px',
            }}>
              <div style={{width:2, height:'100%', background: m.hot?V2_C.hot:m.good?V2_C.signal:V2_C.cool}}/>
            </div>
          ))}
          <div style={{position:'absolute', top:8, bottom:8, left:`${(time/duration)*100}%`, width:2, background:'white', transform:'translateX(-50%)'}}/>
        </div>
        <div style={{display:'flex', justifyContent:'space-between', fontFamily:V2_F.mono, fontSize:9, color:V2_C.mute, letterSpacing:'0.1em', marginTop:4}}>
          <span>0:00</span><span>0:10</span><span>0:20</span><span>0:30</span>
        </div>
      </div>

      {/* moments list — tap to jump */}
      <div style={{marginTop:18}}>
        <V2_MonoTag>MOMENTS · TAP TO JUMP</V2_MonoTag>
        <div style={{marginTop:10, display:'flex', flexDirection:'column', gap:6}}>
          {M_REPORT.markers.map((m,i) => {
            const active = Math.abs(time - m.t) < 1.5;
            const color = m.hot ? V2_C.hot : m.good ? V2_C.signal : V2_C.cool;
            return (
              <button key={i} onClick={()=>seek(m.t)} style={{
                all:'unset', cursor:'pointer',
                display:'grid', gridTemplateColumns:'48px 1fr auto', gap:12, alignItems:'center',
                padding:'14px 14px',
                background: active ? V2_C.ink2 : 'transparent',
                border:`1px solid ${active ? color : V2_C.line}`,
                borderLeft:`3px solid ${color}`,
              }}>
                <div style={{fontFamily:V2_F.mono, fontSize:13, fontWeight:600, color, letterSpacing:'0.05em'}}>{m.t.toFixed(1)}s</div>
                <div>
                  <div style={{fontSize:14, color:V2_C.text}}>{m.label}</div>
                  <div style={{fontFamily:V2_F.mono, fontSize:9, color, letterSpacing:'0.15em', marginTop:2}}>{m.cat}{m.hot?' · ISSUE':m.good?' · STRENGTH':''}</div>
                </div>
                <span style={{fontFamily:V2_F.mono, fontSize:12, color:active?V2_C.signal:V2_C.mute}}>→</span>
              </button>
            );
          })}
        </div>
      </div>
    </section>
  );
}
function fmtM(s){const m=Math.floor(s/60);const r=Math.floor(s%60);return `${m}:${String(r).padStart(2,'0')}`;}

// ── Mobile fix sections ───────────────────────────────────────
function MFixHook() {
  const fx = M_REPORT.fixes[0];
  return (
    <section style={{padding:'40px 22px 32px', position:'relative', overflow:'hidden', borderBottom:`1px solid ${V2_C.line}`}}>
      <V2_Watermark size={360} opacity={0.06} right={-30} top={-40}>01</V2_Watermark>
      <div style={{position:'relative'}}>
        <div style={{display:'flex', alignItems:'center', gap:8, marginBottom:14}}>
          <V2_Pill color={V2_C.hot}>{fx.cat}</V2_Pill>
          <span style={{fontFamily:V2_F.mono, fontSize:10, color:V2_C.hot, letterSpacing:'0.12em'}}>{fx.t}</span>
          <span style={{fontFamily:V2_F.display, fontWeight:600, fontSize:32, color:V2_C.signal, letterSpacing:'-0.03em', marginLeft:'auto', lineHeight:0.9}}>{fx.delta}</span>
        </div>

        <h2 style={{fontFamily:V2_F.display, fontWeight:600, fontSize:24, lineHeight:1.2, letterSpacing:'-0.015em', margin:0}}>
          {fx.diagnosis}
        </h2>

        <div style={{marginTop:18, padding:'16px 18px', background:V2_C.ink2, border:`1px solid ${V2_C.signal}`, position:'relative'}}>
          <div style={{position:'absolute', top:-1, left:-1, background:V2_C.signal, color:V2_C.ink, fontFamily:V2_F.mono, fontSize:9, letterSpacing:'0.15em', padding:'3px 8px', fontWeight:600}}>FIX</div>
          <div style={{fontSize:15, lineHeight:1.5, color:V2_C.text, paddingTop:8}}>{fx.fix}</div>
        </div>

        <div style={{marginTop:22}}>
          <V2_MonoTag>3 REWRITES</V2_MonoTag>
          <div style={{marginTop:10, display:'flex', flexDirection:'column', gap:8}}>
            {fx.rewrites.map((r,i)=>(
              <div key={i} style={{
                padding:'12px 14px',
                background: i===fx.pick?V2_C.signalTint:'transparent',
                border: i===fx.pick?`1px solid ${V2_C.signal}`:`1px solid ${V2_C.line}`,
                position:'relative',
              }}>
                {i===fx.pick && <div style={{position:'absolute', top:-1, right:-1, background:V2_C.signal, color:V2_C.ink, fontFamily:V2_F.mono, fontSize:8, letterSpacing:'0.15em', padding:'2px 6px', fontWeight:600}}>PICK</div>}
                <div style={{display:'flex', justifyContent:'space-between', alignItems:'baseline'}}>
                  <span style={{fontFamily:V2_F.mono, fontSize:9, color:i===fx.pick?V2_C.signal:V2_C.dim, letterSpacing:'0.12em'}}>{r.tone.toUpperCase()}</span>
                  <span style={{fontFamily:V2_F.display, fontWeight:600, fontSize:18, color:V2_C.signal, letterSpacing:'-0.02em'}}>{r.lift}</span>
                </div>
                <div style={{fontFamily:V2_F.sans, fontStyle:'italic', fontSize:14, lineHeight:1.4, color:i===fx.pick?V2_C.text:V2_C.dim, marginTop:8}}>
                  "{r.text}"
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}

function MFixPacing() {
  const fx = M_REPORT.fixes[1];
  return (
    <section style={{padding:'40px 22px 32px', position:'relative', overflow:'hidden', borderBottom:`1px solid ${V2_C.line}`}}>
      <V2_Watermark size={360} opacity={0.06} right={-30} top={-40}>02</V2_Watermark>
      <div style={{position:'relative'}}>
        <V2_Pill color={V2_C.signal}>{fx.cat}</V2_Pill>
        <h2 style={{fontFamily:V2_F.display, fontWeight:600, fontSize:24, lineHeight:1.2, letterSpacing:'-0.015em', margin:'14px 0 0'}}>
          {fx.diagnosis}
        </h2>

        <div style={{marginTop:20, display:'flex', flexDirection:'column', gap:10}}>
          {fx.issues.map((isu,i)=>(
            <div key={i} style={{background:V2_C.ink2, border:`1px solid ${V2_C.line}`, padding:'14px 16px'}}>
              <div style={{display:'flex', justifyContent:'space-between', alignItems:'baseline'}}>
                <div style={{fontFamily:V2_F.display, fontWeight:500, fontSize:22, color:V2_C.signal, letterSpacing:'-0.02em', lineHeight:1}}>{isu.t}</div>
                <span style={{fontFamily:V2_F.mono, fontSize:9, color:V2_C.mute, letterSpacing:'0.15em'}}>ISSUE 0{i+1}</span>
              </div>
              <h3 style={{fontFamily:V2_F.display, fontWeight:500, fontSize:18, lineHeight:1.25, margin:'10px 0 0', letterSpacing:'-0.005em'}}>{isu.head}</h3>
              <p style={{fontSize:13, lineHeight:1.5, color:V2_C.dim, margin:'8px 0 0'}}>{isu.body}</p>
              <button style={{...V2_btn(), marginTop:10, fontSize:9, padding:'7px 11px'}}>↗ JUMP TO {isu.t}</button>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

function MFixThumbnail() {
  const fx = M_REPORT.fixes[2];
  return (
    <section style={{padding:'40px 22px 32px', position:'relative', overflow:'hidden', borderBottom:`1px solid ${V2_C.line}`}}>
      <V2_Watermark size={360} opacity={0.06} right={-30} top={-40}>03</V2_Watermark>
      <div style={{position:'relative'}}>
        <div style={{display:'flex', alignItems:'center', gap:8, marginBottom:14}}>
