// Desktop — final merged report design
// A's filmstrip/structure + C's giant transparent numeral watermarks + real video

const { REPORT } = window;

// ── Shared atoms ──────────────────────────────────────────────
const F = {
  display:"'Clash Display', sans-serif",
  sans:"'Geist', sans-serif",
  mono:"'Geist Mono', monospace",
};
const C = {
  ink:'#0E0D0B', ink2:'#161512', ink3:'#232118',
  line:'rgba(255,245,210,0.08)', lineS:'rgba(255,245,210,0.15)',
  text:'#F5F1E8', dim:'#A8A092', mute:'#6B6557',
  signal:'#C6FF3D', hot:'#FF4A1C', cool:'#4A8CFF',
  hotTint:'rgba(255,74,28,0.12)', signalTint:'rgba(198,255,61,0.06)',
};

function Watermark({ children, opacity = 0.04, size = 460, right = -60, top = -40 }) {
  return (
    <div style={{
      position:'absolute', right, top,
      fontFamily:F.display, fontWeight:700,
      fontSize:size, lineHeight:1,
      color: `rgba(198,255,61,${opacity})`,
      letterSpacing:'-0.06em', pointerEvents:'none',
      userSelect:'none', whiteSpace:'nowrap',
    }}>{children}</div>
  );
}

function MonoTag({children, color = C.mute}) {
  return <div style={{fontFamily:F.mono, fontSize:11, letterSpacing:'0.2em', color, textTransform:'uppercase'}}>{children}</div>;
}
function Pill({children, color = C.mute, bg = 'transparent'}) {
  return <span style={{
    fontFamily:F.mono, fontSize:10, letterSpacing:'0.12em',
    color, background:bg, border:`1px solid ${color}`,
    padding:'4px 8px', textTransform:'uppercase', display:'inline-block',
  }}>{children}</span>;
}

const btn = (variant='ghost') => ({
  fontFamily:F.mono, fontSize:11, fontWeight:600, letterSpacing:'0.12em',
  background: variant === 'primary' ? C.signal : 'transparent',
  color: variant === 'primary' ? C.ink : C.text,
  border: `1px solid ${variant === 'primary' ? C.signal : C.lineS}`,
