// ── VIDEO + TIMELINE ──────────────────────────────────────────
function VideoSection() {
  const [time, setTime] = React.useState(0);
  const [playing, setPlaying] = React.useState(false);
  const [duration, setDuration] = React.useState(REPORT.duration);
  const videoRef = React.useRef(null);

  const seek = (t) => {
    if (videoRef.current) {
      videoRef.current.currentTime = t;
      setTime(t);
    }
  };
  const togglePlay = () => {
    if (!videoRef.current) return;
    if (playing) videoRef.current.pause();
    else videoRef.current.play();
    setPlaying(!playing);
  };

  return (
    <section style={{padding:'56px 56px 48px', borderBottom:`1px solid ${C.line}`, position:'relative'}}>
      <Watermark size={420} opacity={0.025} right={32} top={20}>VIDEO</Watermark>

      <div style={{position:'relative', display:'flex', justifyContent:'space-between', alignItems:'flex-end', marginBottom:24}}>
        <div>
          <MonoTag>THE VIDEO · {REPORT.duration}s RUNTIME</MonoTag>
          <h2 style={{fontFamily:F.display, fontWeight:600, fontSize:42, letterSpacing:'-0.025em', margin:'8px 0 0', color:C.text}}>
            Five moments. <em style={{fontStyle:'italic', color:C.hot}}>Two cost retention.</em>
          </h2>
        </div>
        <div style={{display:'flex', gap:6, alignItems:'center', fontFamily:F.mono, fontSize:10, letterSpacing:'0.1em'}}>
          <Pill color={C.hot}>● HOT</Pill>
          <Pill color={C.signal}>● STRONG</Pill>
        </div>
      </div>

      <div style={{position:'relative', display:'grid', gridTemplateColumns:'1.2fr 1fr', gap:24}}>
        {/* Video player */}
        <div style={{background:C.ink2, border:`1px solid ${C.line}`, position:'relative', overflow:'hidden'}}>
          <video
            ref={videoRef}
            src={REPORT.videoUrl}
            style={{width:'100%', display:'block', aspectRatio:'9/16', maxHeight:520, objectFit:'cover', background:'#000'}}
            muted playsInline
            onTimeUpdate={e => setTime(e.target.currentTime)}
            onLoadedMetadata={e => setDuration(e.target.duration || REPORT.duration)}
            onClick={togglePlay}
          />
          {/* play overlay */}
          {!playing && (
            <button onClick={togglePlay} style={{
              position:'absolute', top:'50%', left:'50%', transform:'translate(-50%,-50%)',
              width:64, height:64, borderRadius:'50%',
              background:'rgba(198,255,61,0.95)', color:C.ink,
              border:'none', cursor:'pointer',
              fontSize:24, fontWeight:700, paddingLeft:6,
              display:'flex', alignItems:'center', justifyContent:'center',
            }}>▶</button>
          )}
          {/* zone overlays */}
          <div style={{position:'absolute', top:0, left:0, right:0, height:'10%', background:'linear-gradient(180deg, rgba(255,74,28,0.4), transparent)', pointerEvents:'none', opacity: time < 2 ? 1 : 0, transition:'opacity 240ms'}}/>
          {/* control bar */}
          <div style={{
            padding:'12px 16px', display:'flex', alignItems:'center', gap:14,
            background:'linear-gradient(180deg, transparent, rgba(0,0,0,0.4))',
            position:'absolute', bottom:0, left:0, right:0,
          }}>
            <button onClick={togglePlay} style={{
              fontFamily:F.mono, fontSize:13, color:'white', background:'transparent', border:'none', cursor:'pointer',
              width:28, height:28, display:'flex', alignItems:'center', justifyContent:'center',
            }}>{playing ? '❚❚' : '▶'}</button>
            <div style={{fontFamily:F.mono, fontSize:11, color:'white', letterSpacing:'0.05em'}}>
              {fmt(time)} / {fmt(duration)}
            </div>
          </div>
        </div>

        {/* Moments panel — clickable seeker */}
        <div style={{display:'flex', flexDirection:'column'}}>
          <MonoTag>MOMENTS · CLICK TO JUMP</MonoTag>
          <div style={{marginTop:14, display:'flex', flexDirection:'column', gap:0, background:C.line, flex:1}}>
            {REPORT.markers.map((m,i) => {
              const active = Math.abs(time - m.t) < 1.5;
              return (
                <div key={i} onClick={()=>seek(m.t)} style={{
                  display:'grid', gridTemplateColumns:'60px 1fr 20px', gap:14, alignItems:'center',
                  padding:'18px 18px',
                  background: active ? C.ink2 : C.ink,
                  cursor:'pointer',
                  borderLeft: `3px solid ${active ? (m.hot ? C.hot : m.good ? C.signal : C.cool) : 'transparent'}`,
                  transition:'all 220ms',
                }}>
                  <div style={{fontFamily:F.mono, fontSize:14, fontWeight:600, color: m.hot ? C.hot : m.good ? C.signal : C.text, letterSpacing:'0.05em'}}>
                    {m.t.toFixed(1)}s
                  </div>
                  <div>
                    <div style={{fontFamily:F.sans, fontSize:14, color:C.text, fontWeight: active ? 500 : 400}}>{m.label}</div>
                    <div style={{fontFamily:F.mono, fontSize:10, color: m.hot ? C.hot : m.good ? C.signal : C.mute, letterSpacing:'0.15em', marginTop:3}}>
                      {m.cat} {m.hot ? '· ISSUE' : m.good ? '· STRENGTH' : ''}
                    </div>
                  </div>
                  <span style={{fontFamily:F.mono, fontSize:11, color: active ? C.signal : C.mute}}>→</span>
                </div>
              );
            })}
          </div>
        </div>
      </div>

      {/* TIMELINE STRIP with frame thumbs */}
      <div style={{marginTop:24, position:'relative'}}>
        <MonoTag>SCRUB · 0:00 → 0:30</MonoTag>
        <div style={{
          position:'relative', marginTop:12,
          background:C.ink2, border:`1px solid ${C.line}`,
          padding:'16px 18px',
        }}>
          {/* frame thumbs row */}
          <div style={{display:'flex', gap:6, height:88}}>
            {REPORT.frames.map((f,i) => (
              <div key={i} onClick={()=>seek(f.t)} style={{
                flex:1, position:'relative', cursor:'pointer',
                background: f.hot ? 'linear-gradient(180deg, rgba(255,74,28,0.25), rgba(0,0,0,0.7))' :
                            f.good ? 'linear-gradient(180deg, rgba(198,255,61,0.25), rgba(0,0,0,0.7))' :
                            'linear-gradient(180deg, #2a3142, #131726)',
                outline: f.hot ? `1px solid ${C.hot}` : f.good ? `1px solid ${C.signal}` : `1px solid ${C.line}`,
                overflow:'hidden',
              }}>
                <div style={{position:'absolute', top:6, left:6, fontFamily:F.mono, fontSize:9, color: f.hot ? C.hot : f.good ? C.signal : 'rgba(255,255,255,0.5)', letterSpacing:'0.1em'}}>
                  {f.t.toFixed(1)}s
                </div>
