                }}>{m.t.toFixed(1)}s</div>
              </div>
            ))}
            {/* playhead */}
            <div style={{
              position:'absolute', top:8, bottom:8,
              left:`${(time/duration)*100}%`,
              width:2, background:'white',
              transform:'translateX(-50%)',
              boxShadow:'0 0 0 2px rgba(0,0,0,0.4)',
