      best = i
      bestLift = rewrites[i].predictedLift
    }
  }
  return best
}

/** "+25" string suitable for the giant numeral on the right of FixHook. */
export function topLiftDisplay<T extends { predictedLift: number }>(
  rewrites: T[],
