@import "tailwindcss";

/* ─────────────────────────────────────────────────────────────
   METRIC.fyi — Lab Lime token system
   Editor-dark base + lime signal + paper for the public report.
   Design source: designs/desktop/8x1/project/palette.jsx
   ───────────────────────────────────────────────────────────── */

@theme {
  /* ── Surfaces ── */
  --color-ink: #0E0D0B;        /* warm near-black, app bg */
  --color-ink-2: #161512;      /* card */
  --color-ink-3: #232118;      /* hover / border */

  /* ── Lines ── */
  --color-line: rgba(255, 245, 210, 0.08);

  /* ── Paper (public report only) ── */
  --color-paper: #F5F1E8;
  --color-paper-2: #ECE6D4;
  --color-bone: #DDD4BA;

  /* ── Text ── */
  --color-text: #F5F1E8;
  --color-text-dim: #A8A092;
  --color-text-mute: #6B6557;

  /* ── Signals ── */
  --color-signal: #C6FF3D;     /* radioactive lime — the score */
  --color-signal-dim: #93C42B;
  --color-hot: #FF4A1C;        /* alarm orange-red — weak hooks */
  --color-hot-tint: rgba(255, 74, 28, 0.12);
  --color-cool: #4A8CFF;       /* citation blue */
  --color-gold: #E8B14A;

  /* ── Fonts (loaded by app/layout.tsx via next/font) ── */
  --font-display: var(--font-clash);
  --font-italic: var(--font-geist), serif;
  --font-sans: var(--font-geist), -apple-system, sans-serif;
  --font-mono: var(--font-geist-mono), "SF Mono", monospace;
}

html, body {
  background: var(--color-ink);
  color: var(--color-text);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

* {
  box-sizing: border-box;
}

/* Selection — match the brand */
::selection {
  background: var(--color-signal);
  color: var(--color-ink);
}

/* Focus ring — lime, not browser blue */
:focus-visible {
  outline: 2px solid var(--color-signal);
  outline-offset: 2px;
}

