                top: 14,
                height: 6,
                background: "rgba(255,255,255,0.06)",
              }}
            />
            <div
              aria-hidden
              className="absolute left-0"
              style={{
                top: 14,
                height: 6,
                background: "var(--color-signal)",
                width: `${pct(currentTime)}%`,
              }}
            />
            {markers.map((m, i) => {
              const color = m.hot
                ? "var(--color-hot)"
                : m.good
                  ? "var(--color-signal)"
                  : "var(--color-cool)"
              return (
                <button
                  key={`scrub-${i}`}
