                  title={`${m.t.toFixed(1)}s · ${m.label}`}
                  className="absolute cursor-pointer"
                  style={{
                    left: `${pct(m.t)}%`,
                    transform: "translateX(-50%)",
                    top: 0,
                    bottom: 0,
                    padding: "0 6px",
                    background: "transparent",
                    border: "none",
