        style={{
          fontFamily: "var(--font-mono)",
          fontSize: 14,
          fontWeight: 600,
          color: marker.hot
            ? "var(--color-hot)"
            : marker.good
              ? "var(--color-signal)"
              : "var(--color-text)",
