                }}
                activeCitationId={activeCitationId}
              />
            ))}
          </div>
        </div>
      </div>

      {/* Timeline strip: frame thumbs + scrubber + time scale */}
      <div className="relative mt-6">
        <MonoTag>SCRUB · 0:00 → {fmtTime(dur)}</MonoTag>
        <div
          className="relative mt-3 p-4"
          style={{
            background: "var(--color-ink-2)",
