                    : f.good
                      ? "linear-gradient(180deg, rgba(198,255,61,0.25), rgba(0,0,0,0.7))"
                      : "linear-gradient(180deg, #2a3142, #131726)",
                  outline: f.hot
                    ? "1px solid var(--color-hot)"
                    : f.good
                      ? "1px solid var(--color-signal)"
