      )}
      <div className="mt-8">
        <MonoTag>3 REWRITES</MonoTag>
        <RewritesGrid
          rewrites={analysis.caption.rewrites.map((r) => ({
            tone: r.tone,
            text: r.text,
            predictedLift: r.predictedLift,
          }))}
          pickIdx={pick}
        />
      </div>
    </FixSectionShell>
  )
}

