}) {
  const isHot = cat === "HOOK"
  const hasRight = !!rightCol

  return (
    <section
      className="relative overflow-hidden border-b px-6 md:px-14 py-12 md:py-18"
      style={{ borderColor: "var(--color-line)" }}
