        >
          {f.t.toFixed(1)}s
        </div>
        <div
          className="absolute bottom-1.5 left-1.5 right-1.5 truncate z-10"
          style={{
            fontFamily: "var(--font-mono)",
            fontSize: 8,
            color: "rgba(255,255,255,0.95)",
            letterSpacing: "0.1em",
            textTransform: "uppercase",
            textShadow: "0 1px 2px rgba(0,0,0,0.7)",
          }}
        >
          {f.label}
        </div>
      </button>
    )
  })}
</div>

