        exit={{ opacity: 0, scale: 0.96, y: 8 }}
        transition={{ duration: 0.26, ease }}
        onClick={(e) => e.stopPropagation()}
        className="relative w-full max-w-[720px] max-h-[88vh] overflow-y-auto"
        style={{
