        rewrites: {
          type: "array",
          items: {
            type: "object",
            required: ["tone", "text", "predictedLift"],
            properties: {
              tone: {
                type: "string",
                enum: [
                  "Curiosity",
                  "Contradiction",
                  "Stat",
                  "Conversational",
                ],
              },
              text: { type: "string" },
              predictedLift: { type: "integer" },
            },
          },
        },
      },
    },
    comparison: {
      type: "object",
      required: ["vsCategoryMedian", "ceilingScore", "inferredCategory"],
      properties: {
        vsCategoryMedian: { type: "integer" },
        ceilingScore: { type: "integer", minimum: 0, maximum: 100 },
        inferredCategory: { type: "string" },
      },
    },
    trending: {
      type: "object",
      required: ["audio", "hashtags"],
      properties: {
        audio: {
          type: "array",
          items: {
            type: "object",
            required: ["name", "why"],
            properties: {
              name: { type: "string" },
              why: { type: "string" },
            },
          },
